<div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Product Integration</div><nav class="os-nav"><a href="product_catalog.php"><i class="dot"></i>Catalog</a><a href="product_quotes.php"><i class="dot"></i>Saved Quotes</a><a class="active" href="product_sales_center.php"><i class="dot"></i>Product Sales</a><a href="operations_center.php"><i class="dot"></i>Operations</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 12A • Product Sale Trace</div><h1><?= $error?'Product Sale review required':'Business OS Order #'.(int)$order['id'] ?></h1><p>Every line below is a frozen snapshot from the finalized Product & Price Pro quote. Product names, Stock No., quantity, unit price and VP remain traceable even after future catalog price changes.</p></section><?php if($error):?><div class="pp-alert bad"><strong>Sale diagnostic:</strong> <?= product_h($error) ?></div><?php else:?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-8"><div class="os-title-row"><div><h2><?= product_h($order['quote_code']?:'Product Sale') ?></h2><p><?= product_h((string)$order['order_date']) ?> • <?= product_h($order['pricing_tier_code']?:'—') ?></p></div><span class="pp-badge">ORDER #<?= (int)$order['id'] ?></span></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Stock</th><th>Product</th><th>Qty</th><th>Unit MRP</th><th>Unit Price</th><th>Line Price</th><th>VP</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><b><?= product_h($i['stock_no']) ?></b></td><td><?= product_h($i['product_name_snapshot']) ?></td><td><?= product_h(psd_num($i['quantity'])) ?></td><td><?= psd_money($i['unit_mrp']) ?></td><td><?= psd_money($i['unit_price']) ?></td><td><?= psd_money($i['line_price']) ?></td><td><?= product_h(psd_num($i['line_vp'])) ?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="7">No line item snapshots found.</td></tr><?php endif;?></tbody></table></div></article><aside class="os-card pp-span-4"><h2>Business Mapping</h2><div class="pp-source"><b>Customer snapshot</b><span><?= product_h($order['customer_name']?:'—') ?></span></div><div class="pp-source"><b>Verified member link</b><span><?= product_h($order['member_name']?:'Not linked') ?><?= $order['member_id']?' #'.(int)$order['member_id']:'' ?></span></div><div class="pp-source"><b>Gross</b><span><?= psd_money($order['gross_amount']) ?></span></div><div class="pp-source"><b>Discount/Saving</b><span><?= psd_money($order['discount_amount']) ?></span></div><div class="pp-source"><b>Net</b><span><?= psd_money($order['net_amount']) ?></span></div><div class="pp-source"><b>Volume Points</b><span><?= product_h(psd_num($order['volume_points'])) ?></span></div><div class="pp-source"><b>Profit</b><span><?= psd_money($order['profit_amount']) ?> • deferred basis</span></div><div class="pp-source"><b>Raw Source ID</b><span>#<?= (int)$order['source_record_id'] ?></span></div></aside></section><div class="os-footer-note"><strong>Trace policy:</strong> this Business OS order points to an immutable Product Sale raw-source record. Future product price updates do not rewrite this finalized sale snapshot.</div><?php endif;?></main></div></body></html>